# Edição editorial: conteúdo integral e navegação independente das redes sociais.
def section(k,t,body,cls=''):
 return f'<section class="wrap section {cls}"><p class="eyebrow">{k}</p><h2>{t}</h2>{body}</section>'
def blocks(items):
 return '<div class="editorial-grid">'+''.join(f'<article><span class="mini-index">0{i}</span><h3>{t}</h3><p>{v}</p></article>' for i,(t,v) in enumerate(items,1))+'</div>'
def add_before_footer(name,body):
 f=p/name; f.write_text(f.read_text().replace('</main>',body+'</main>'))
landscape='''<div class="landscape" aria-hidden="true"><svg viewBox="0 0 800 680" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#233f39"/><stop offset="1" stop-color="#6e8a70"/></linearGradient><pattern id="grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0V45" fill="none" stroke="#ffffff" stroke-opacity=".06"/></pattern></defs><path fill="url(#sky)" d="M0 0h800v680H0z"/><path fill="url(#grid)" d="M0 0h800v680H0z"/><circle cx="565" cy="160" r="75" fill="#ebc582"/><g fill="none" stroke="#d5ddc1" opacity=".25"><circle cx="565" cy="160" r="103"/><circle cx="565" cy="160" r="128"/><path d="M565 10v300M415 160h300"/></g><path d="M0 450L195 180l160 210 120-85 325 260v115H0" fill="#597961"/><path d="M0 545L255 317l175 191 175-222L800 489v191H0" fill="#365b4b"/><path d="M0 578q210-200 435-14T800 510v170H0" fill="#1e4439"/><path d="M0 650q160-90 365-35t435-15v80H0" fill="#112f28"/><path d="M560 490q-130 20-105 55t-30 58-120 77" fill="none" stroke="#e6c38b" stroke-width="3" stroke-dasharray="6 9"/><g fill="#dba760"><path d="M486 486l70-92 70 92z"/><path d="M556 394v92h70z" fill="#b27a42"/><path d="M556 435l-27 51h54z" fill="#203a30"/></g><g fill="#173c30"><path d="M75 556l44-102h-21l35-80 37 80h-22l45 102zM633 578l47-112h-22l40-94 40 94h-23l47 112z"/></g><g fill="#edd5a6"><circle cx="110" cy="110" r="2"/><circle cx="265" cy="90" r="2"/><circle cx="385" cy="192" r="2"/></g></svg><span class="land-label">NATUREZA · AMIZADE · DESCOBERTA</span><div class="expedition-stamp">194 / SP<small>SÃO JOÃO DA BOA VISTA</small></div></div>'''
hero='''<section class="new-hero"><div class="hero-editorial"><p class="eyebrow light">GRUPO ESCOTEIRO MARECHAL RONDON</p><h1>Há um mundo<br>lá fora.<br><em>Vamos juntos?</em></h1><p>Desde 1969, um lugar para descobrir a natureza, construir amizades e crescer fazendo a diferença em São João da Boa Vista.</p><div class="actions"><a class="button orange" href="participar.html">Quero fazer parte <span>↗</span></a><a class="hero-link" href="grupo.html">Conheça nossa história</a></div><div class="hero-signature"><span>19.04.1969</span><span>Uma história que atravessa gerações.</span></div></div>'''+landscape+'''</section><div class="heritage-bar"><span><b>57</b> anos de história</span><span><b>4</b> ramos, muitas descobertas</span><span><b>194/SP</b> raízes em São João</span><a href="grupo.html">Conheça o Rondon <b>↗</b></a></div>'''
introhome=section('CRESCER É UMA AVENTURA','O que se aprende aqui<br><em>vai para a vida.</em>','''<div class="manifesto"><p class="lead">Montar uma barraca é só o começo. Por trás de cada desafio, há uma oportunidade de aprender a ouvir, tomar decisões, cuidar do outro e confiar nas próprias capacidades.</p><p>No escotismo, crianças e jovens participam de experiências que unem ação e reflexão. A natureza é espaço de descoberta; o grupo, espaço de convivência. Cada etapa traz novas responsabilidades, respeitando o caminho de quem está crescendo.</p></div>'''+blocks([('Aprender fazendo','Experimentar, tentar de novo e perceber o próprio progresso. O conhecimento ganha sentido quando faz parte de uma experiência.'),('Viver em equipe','Dividir tarefas, ouvir ideias diferentes e construir soluções em conjunto. A amizade também se fortalece no cuidado cotidiano.'),('Deixar uma contribuição','Olhar para a comunidade e reconhecer onde podemos ajudar. Boas ações dão forma ao compromisso com um mundo melhor.')]))
photosection='''<section class="wrap field-note"><figure><img src="assets/equipe.jpg" alt="Cerimônia ao ar livre do Grupo Escoteiro Marechal Rondon" loading="lazy"><figcaption>Do nosso acervo · encontro e formação, 2026</figcaption></figure><div><p class="eyebrow">PESSOAS QUE FAZEM A HISTÓRIA</p><h2>Um lenço.<br>Muitas gerações.<br><em>O mesmo propósito.</em></h2><p>O Marechal Rondon é feito de jovens, famílias e adultos voluntários. Gente que reserva tempo para ensinar, aprender e transformar encontros em memórias.</p><p>Nossa história começou em 19 de abril de 1969. Continua nas atividades, nas pequenas conquistas e na disposição de servir à cidade que é nossa casa.</p><a class="text-link" href="grupo.html">Percorra nossa história ↗</a></div></section>'''
branches=section('UMA JORNADA EM QUATRO ETAPAS','Cada idade abre<br><em>um novo horizonte.</em>','''<div class="branches"><a class="branch yellow" href="ramos.html#lobinho"><span>01 / RAMO LOBINHO</span><div class="branch-symbol" aria-hidden="true">✳</div><h3>O encanto<br>de descobrir.</h3><p>Histórias, jogos e pequenas responsabilidades na vida em alcateia.</p><b>Conheça o ramo ↗</b></a><a class="branch green" href="ramos.html#escoteiro"><span>02 / RAMO ESCOTEIRO</span><div class="branch-symbol" aria-hidden="true">⌁</div><h3>A aventura<br>de explorar.</h3><p>Amizade e cooperação na patrulha, com desafios ao ar livre.</p><b>Conheça o ramo ↗</b></a><a class="branch red" href="ramos.html#senior"><span>03 / RAMO SÊNIOR</span><div class="branch-symbol" aria-hidden="true">↗</div><h3>A coragem<br>de ir além.</h3><p>Projetos, escolhas e experiências com mais autonomia.</p><b>Conheça o ramo ↗</b></a><a class="branch blue" href="ramos.html#pioneiro"><span>04 / RAMO PIONEIRO</span><div class="branch-symbol" aria-hidden="true">✦</div><h3>A vontade<br>de transformar.</h3><p>Serviço à comunidade e projetos que conectam propósito e ação.</p><b>Conheça o ramo ↗</b></a></div>''')
diary='<section class="section pale"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">CADERNO DE CAMPO</p><h2>Histórias do nosso caminho.</h2></div><a class="text-link" href="novidades.html">Explore o diário ↗</a></div><div class="cards">'+''.join(card(d) for d in posts[:3])+'</div></div></section>'
impact='''<section class="impact"><div class="wrap impact-grid"><div><p class="eyebrow light">O COMPROMISSO VIRA AÇÃO</p><h2>Uma cidade melhor<br>se faz <em>em conjunto.</em></h2><p>O serviço à comunidade faz parte da nossa história. Da coleta de óleo usado à mobilização por doações, aprender a ajudar é também aprender a enxergar o outro.</p><a class="button cream" href="projetos.html">Conheça os projetos ↗</a></div><div class="impact-list"><article><span>01</span><div><h3>Cuidado com o ambiente</h3><p>Coleta de óleo usado e atenção aos hábitos que impactam o lugar onde vivemos.</p></div></article><article><span>02</span><div><h3>Solidariedade na prática</h3><p>Campanhas que mobilizam jovens e famílias em torno de necessidades concretas.</p></div></article><article><span>03</span><div><h3>Voluntariado que aproxima</h3><p>Tempo, experiência e disposição para construir oportunidades educativas.</p></div></article></div></div></section>'''
welcome=section('SEU PRIMEIRO PASSO','Toda grande história<br><em>começa com um encontro.</em>','''<div class="welcome-grid"><div><p class="lead">Não é preciso conhecer nós, trilhas ou acampamentos para chegar. A curiosidade é um ótimo começo.</p><p>Preparamos um guia para famílias, jovens e adultos que querem conhecer o grupo: como funciona a participação, o que perguntar antes da visita e como colaborar.</p><a class="button green-button" href="participar.html">Leia o guia de participação ↗</a></div><aside class="visit-card"><p class="eyebrow">NOSSO PONTO DE ENCONTRO</p><h3>Parque das Bromélias</h3><p>Av. Jorge Estevam Rodrigues, 1725<br>São João da Boa Vista · SP</p><p class="small">Combine dia e horário antes da visita.</p><a class="text-link" href="contato.html">Localização e contato ↗</a></aside></div>''')
support='''<section class="support-call wrap"><span class="support-mark" aria-hidden="true">✳</span><div><p class="eyebrow">CADA GESTO CONTA</p><h2>Ajude a próxima<br>aventura a acontecer.</h2><p>Materiais, parcerias, tempo e conhecimento: há muitas formas de caminhar com o grupo.</p></div><a class="button green-button" href="apoie.html">Descubra como apoiar ↗</a></section>'''
write('index.html','Há um mundo lá fora. Vamos juntos?',hero+introhome+photosection+branches+diary+impact+welcome+support)

article_sections={
'aprendizado-e-aventura':[('Aprendizado que se compartilha','O registro de setembro de 2026 apresenta um fim de semana de Ponta de Lança e Ponta de Flecha. A publicação destaca o aprendizado e a troca de experiências, dois elementos que ajudam a dar continuidade à vida do grupo.'),('O valor de aprender com outras pessoas','No escotismo, aprender não se limita a receber uma explicação. Observar, conversar e experimentar são formas de construir conhecimento. Quando uma experiência é compartilhada, ela pode inspirar novas perguntas e novas maneiras de participar.'),('Da experiência ao cotidiano','A convivência em grupo oferece oportunidades para ouvir opiniões, dividir responsabilidades e reconhecer o que cada pessoa pode acrescentar. Esse é o sentido educativo que dá valor aos encontros, além de qualquer técnica ou tarefa específica.'),('Continue a descoberta','Para entender como as experiências se organizam nas diferentes etapas da vida escoteira, conheça os ramos do Marechal Rondon. Cada um tem uma proposta própria, ligada ao desenvolvimento dos jovens.')],
'formacao-de-chefes':[('O cuidado começa na preparação','Em agosto de 2026, o Marechal Rondon compartilhou registros de formação de chefes. O grupo também publicou encontros de Indaba, dedicados à troca e ao planejamento. Esses momentos mostram uma parte do escotismo que nem sempre aparece durante as atividades: a preparação dos adultos.'),('Quem acompanha também aprende','Atuar como voluntário envolve disponibilidade para aprender e refletir sobre a própria atuação. A formação ajuda os adultos a compreender a proposta educativa e a pensar em experiências adequadas aos jovens que acompanham.'),('Planejar com intenção','Uma atividade pode parecer apenas um jogo para quem a observa de fora. Sua preparação, porém, envolve pensar no propósito, na participação dos jovens e nas condições necessárias para realizá-la. Conversar com outros adultos permite compartilhar dúvidas e ampliar o repertório.'),('Uma forma de contribuir','O escotismo também é um caminho de participação para adultos. Quem deseja colaborar pode conversar com a equipe sobre as funções, a disponibilidade necessária e o processo de preparação. O primeiro passo é conhecer o grupo e suas necessidades.')],
'57-anos':[('Uma história que começa em 1969','Em 19 de abril de 1969, começou a trajetória do Grupo Escoteiro Marechal Rondon em São João da Boa Vista. Em abril de 2026, essa caminhada completou 57 anos. O aniversário celebra a continuidade de um trabalho construído por muitas pessoas ao longo do tempo.'),('Memória de quem abriu o caminho','Nos registros históricos do grupo aparecem Milton Ribeiro e sua esposa, José Wilson de Souza, conhecido como Tupi, e Benedito Juvêncio entre os fundadores. Preservar esses nomes é reconhecer que a história de uma instituição começa com pessoas dispostas a realizá-la.'),('Reconhecimento e permanência','A trajetória inclui o reconhecimento municipal de utilidade pública, em 1994, e a celebração dos 50 anos, em 2019, com o recebimento do Troféu Jatobá. São marcos que ajudam a contar a presença do escotismo na cidade.'),('A próxima página ainda está sendo escrita','Um grupo não vive apenas das lembranças. Sua continuidade depende dos jovens que chegam, das famílias que participam e dos adultos que compartilham tempo e experiência. Fazer parte do Marechal Rondon é também ajudar a construir o que virá depois.')],
'oleo-usado':[('Uma campanha que continua','O Marechal Rondon divulgou a continuidade da coleta de óleo usado em 2026. A iniciativa oferece à comunidade uma oportunidade de participar de uma ação ambiental ligada ao grupo.'),('Como organizar sua participação','Antes de levar o material, converse com a equipe para confirmar a forma de acondicionamento aceita, o local e o horário da entrega. Espere o óleo esfriar antes de manuseá-lo e mantenha o recipiente bem fechado durante o transporte. Não misture outros produtos ao material destinado à coleta.'),('Para volumes maiores','A publicação orienta consultar o grupo sobre a possibilidade de retirada de grandes quantidades. Essa possibilidade precisa ser combinada: não representa um serviço permanente de coleta nem dispensa a confirmação da equipe.'),('Um hábito que aproxima a comunidade','A campanha é uma forma de envolver famílias, vizinhos e estabelecimentos em torno de uma atitude concreta. Para ajudar, comece organizando a entrega do seu próprio material e compartilhe a orientação de combinar previamente com o grupo.')],
'nova-diretoria':[('Uma assembleia para olhar o caminho','Em 17 de janeiro de 2026, a Assembleia Ordinária do Marechal Rondon reuniu relatos das atividades de 2025, prestação de contas e eleição da Diretoria e da Comissão Fiscal. O mandato informado segue até janeiro de 2028.'),('A diretoria eleita','Ulisses Valin foi eleito diretor-presidente; Pedro Hernandez, diretor administrativo; e Mariana Zorgetto, diretora financeira. A composição reúne as funções de direção e organização necessárias à continuidade do grupo.'),('Comissão Fiscal','Foram eleitos Fabio Mucin, Marta Bonfante e Luis Fernando Silvestre para a Comissão Fiscal. A identificação dos integrantes permite que famílias e comunidade conheçam a estrutura institucional apresentada na assembleia.'),('Informação e participação','A vida do grupo envolve tanto a programação educativa quanto a organização que a torna possível. Dúvidas sobre documentos, participação institucional ou informações da assembleia podem ser encaminhadas à diretoria pelo canal de contato do Marechal Rondon.')],
'grupo-padrao-ouro':[('Um reconhecimento compartilhado','O Marechal Rondon anunciou em 2026 a conquista de Grupo Padrão Ouro. Na publicação, o grupo celebrou o empenho dos chefes e dos jovens, reconhecendo o trabalho de quem participa da sua construção cotidiana.'),('Além de uma conquista','Para a comunidade do grupo, esse anúncio é uma oportunidade de valorizar a dedicação coletiva. Atividades, preparação e continuidade dependem de pessoas que assumem tarefas e mantêm vivo o compromisso com o escotismo.'),('Reconhecer quem participa','Uma conquista institucional ganha significado quando é compartilhada com jovens, voluntários e famílias. Cada contribuição ajuda a sustentar o ambiente em que as experiências educativas acontecem.'),('Uma história em movimento','O reconhecimento se soma a uma trajetória iniciada em 1969. Conheça a história do Marechal Rondon e os projetos que conectam o grupo à comunidade de São João da Boa Vista.')]
}
for d in posts:
 body='<div class="article-layout"><aside class="article-index"><p class="eyebrow">NESTA HISTÓRIA</p>'+''.join(f'<a href="#parte-{i}">{t}</a>' for i,(t,_) in enumerate(article_sections[d['slug']],1))+'</aside><div class="article-copy"><p class="lead">'+html.escape(d['text'])+'</p>'+''.join(f'<section id="parte-{i}"><h2>{t}</h2><p>{txt}</p></section>' for i,(t,txt) in enumerate(article_sections[d['slug']],1))+f'<details class="source-note"><summary>Fonte e contexto deste relato</summary><p>Relato elaborado a partir da publicação do grupo. Os trechos explicativos apresentam contexto educativo; não acrescentam participantes, resultados ou atividades não documentados.</p><a class="text-link" href="{d["url"]}" target="_blank" rel="noopener">Consultar registro original ↗</a></details><div class="share"><button class="button outline" data-share>Compartilhar história ↗</button><span role="status" id="share-status"></span></div></div></div>'
 related='<section class="wrap section"><p class="eyebrow">CONTINUE PELO NOSSO DIÁRIO</p><h2>Outras histórias do Rondon.</h2><div class="cards">'+''.join(card(x) for x in posts if x!=d)[:0]+'</div></section>'
 related='<section class="wrap section"><p class="eyebrow">CONTINUE PELO NOSSO DIÁRIO</p><h2>Outras histórias do Rondon.</h2><div class="cards">'+''.join(card(x) for x in [x for x in posts if x!=d][:3])+'</div></section>'
 write(d['slug']+'.html',d['title'],intro(d['category']+' / '+d['date'],d['title'],'Histórias, pessoas e aprendizados do Marechal Rondon.')+'<article class="wrap article-full">'+body+'</article>'+related,'novidades.html')

add_before_footer('grupo.html',section('O QUE NOS UNE','Uma presença local.<br>Um compromisso para a vida.',blocks([('Jovens no centro','O sentido do grupo está nas experiências de crianças e jovens. Participar é encontrar oportunidades de aprender, conviver e assumir responsabilidades progressivamente.'),('Famílias por perto','O diálogo entre famílias e equipe ajuda a acompanhar essa caminhada. Conhecer a proposta, conversar sobre expectativas e participar da vida do grupo fortalece essa relação.'),('Adultos que se dedicam','O trabalho voluntário reúne pessoas com experiências diferentes. Além das atividades com os jovens, há tarefas de organização, administração e cuidado com o espaço.')]))+section('MEMÓRIA E CONTINUIDADE','O passado inspira.<br>O presente convida.','<div class="manifesto"><p class="lead">Em 2019, a celebração dos 50 anos e o Troféu Jatobá marcaram uma trajetória que já atravessava gerações. Em 2026, o grupo segue escrevendo novos capítulos.</p><p>A sede no Parque das Bromélias é um ponto de encontro dessa história. Mais do que um endereço, representa o lugar em que pessoas se reúnem para planejar, aprender e compartilhar a vida escoteira. A autorização municipal de uso da área aparece na Lei nº 3.955/2016; o documento pode ser consultado nas referências institucionais.</p></div><a class="button green-button" href="participar.html">Encontre seu lugar nessa história ↗</a>'))

branch_more={
'lobinho':('Aprender com a imaginação','A alcateia reúne os lobinhos em pequenos grupos chamados matilhas. Histórias e brincadeiras, inspiradas no universo do Livro da Jângal, ajudam a dar sentido às experiências. A boa ação e o cuidado com os outros aparecem em situações próximas da vida das crianças.','Jogos cooperativos, histórias, contato com a natureza e descobertas de habilidades são exemplos da proposta do ramo. As atividades concretas dependem da programação da equipe.'),
'escoteiro':('A patrulha como espaço de crescimento','A vida em pequenos grupos abre espaço para dividir tarefas, participar de decisões e aprender com os companheiros. A aventura ao ar livre dá contexto a desafios e à construção de autonomia.','Acampamentos, exploração, habilidades práticas e projetos em equipe fazem parte do repertório educativo do ramo. Não é necessário chegar sabendo: aprender faz parte da jornada.'),
'senior':('Desafios com mais protagonismo','O ramo amplia as oportunidades de participação dos jovens em escolhas e projetos. Conhecer os próprios limites, trabalhar com outras pessoas e refletir sobre experiências fazem parte desse caminho.','O desafio tem valor quando ajuda a crescer. Projetos e atividades podem reunir planejamento, execução e avaliação, conectando interesses pessoais às responsabilidades com o grupo.'),
'pioneiro':('Um projeto de vida em construção','No clã, o serviço e os projetos ajudam a conectar escolhas pessoais com participação na comunidade. É um espaço para trocar experiências e transformar intenções em ações.','Identificar uma necessidade, planejar uma contribuição e avaliar seu resultado são caminhos possíveis para aprender servindo. A convivência oferece apoio à construção de autonomia e de propósito.')}
f=p/'ramos.html'; txt=f.read_text()
for slug,(title,a,b) in branch_more.items():
 start=txt.index(f'id="{slug}"'); end=txt.index('<a class="text-link"',start)
 txt=txt[:end]+f'<h3>{title}</h3><p>{a}</p><p>{b}</p><p class="small">Referência educativa: <a class="inline-link" href="https://www.escoteiros.org.br/ramo-{slug}/" target="_blank" rel="noopener">Escoteiros do Brasil ↗</a></p>'+txt[end:]
f.write_text(txt)
add_before_footer('participar.html',section('UM GUIA PARA AS FAMÍLIAS','Chegar com tranquilidade<br>faz parte da experiência.','''<div class="welcome-grid"><div><h3>Antes de sair de casa</h3><p>Combine a visita e informe a idade de quem deseja participar. Pergunte se a atividade será na sede ou em outro local, qual é o horário de chegada e se há alguma orientação específica para o encontro.</p><p>Prefira roupas confortáveis e calçado adequado à atividade combinada. Consulte a equipe sobre água, proteção para o sol e outros itens. Não é necessário comprar uniforme ou equipamentos antes de receber orientação.</p><h3>Na primeira conversa</h3><p>Conte o que motivou o interesse pelo escotismo e apresente suas dúvidas. É também o momento de conversar, de forma reservada, sobre cuidados ou necessidades que possam influenciar a participação.</p></div><aside class="visit-card"><p class="eyebrow">PERGUNTAS QUE AJUDAM</p><ul class="check-list"><li>Qual ramo corresponde à idade?</li><li>Há vagas disponíveis?</li><li>Como funciona a primeira visita?</li><li>Quais documentos são necessários?</li><li>Como funcionam materiais e contribuições?</li><li>Como as famílias recebem os comunicados?</li></ul></aside></div>''')+section('VOLUNTARIADO','Seu conhecimento também<br>pode abrir caminhos.',blocks([('Na atividade educativa','Quem deseja acompanhar crianças e jovens pode conhecer a atuação dos escotistas. Converse sobre responsabilidades, formação e disponibilidade antes de assumir uma função.'),('Na organização do grupo','Administração, planejamento e cuidado com recursos também precisam de pessoas. Habilidades profissionais e experiência de vida podem contribuir para essas tarefas.'),('Em uma colaboração pontual','Uma oficina, um serviço ou o apoio a um projeto podem ser formas de começar. Toda participação deve ser combinada com a equipe responsável.')])) )
add_before_footer('projetos.html',section('PARTICIPAR COM PROPÓSITO','Uma boa ação começa<br>com uma necessidade real.',blocks([('Entender','Antes de mobilizar uma campanha, é preciso conhecer o que será útil para quem recebe. Consulte a equipe sobre as ações em andamento e os itens necessários.'),('Organizar','Combine quantidades, condições dos materiais e a entrega. Uma contribuição planejada facilita o trabalho de quem arrecada e de quem recebe.'),('Compartilhar','Envolver outras pessoas amplia o alcance das ações. Divulgue orientações confirmadas e preserve a dignidade de quem é beneficiado.')])) )
add_before_footer('apoie.html',section('FORMAS DE CAMINHAR JUNTO','Apoiar é tornar<br>novas experiências possíveis.','''<div class="welcome-grid"><div><h3>Para famílias e amigos</h3><p>Doar materiais em boas condições, colaborar com uma campanha ou oferecer uma habilidade são possibilidades de apoio. Antes de separar os itens, confirme se atendem às necessidades do momento.</p><h3>Para empresas e profissionais</h3><p>Uma parceria pode envolver materiais, serviços ou conhecimento. Apresente sua ideia à diretoria para avaliar o que faz sentido para o grupo e combinar a forma de colaboração.</p><h3>Contribuições financeiras</h3><p>Converse com a diretoria sobre o canal de doação disponível. A equipe pode orientar a identificação da contribuição e esclarecer dúvidas sobre sua destinação.</p></div><aside class="visit-card"><p class="eyebrow">COMBINE SUA COLABORAÇÃO</p><h3>Três informações ajudam muito.</h3><ol><li>O que você gostaria de oferecer.</li><li>A quantidade ou disponibilidade.</li><li>Como e quando poderia entregar.</li></ol><a class="button green-button" href="contato.html">Fale com o grupo ↗</a></aside></div>'''))
write('agenda.html','Agenda e encontros',intro('ORGANIZE SUA PARTICIPAÇÃO','O próximo encontro<br>começa por aqui.','Entenda os tipos de atividade e saiba o que confirmar antes de participar.')+section('O RITMO DA VIDA ESCOTEIRA','Cada encontro tem um propósito.',blocks([('Atividades do grupo','Encontros de cada ramo podem reunir jogos, habilidades, projetos e momentos de convivência. A programação é organizada pela equipe e comunicada às famílias.'),('Saídas e acampamentos','Atividades externas têm orientações próprias. Local, transporte, autorização e materiais precisam ser confirmados para cada ocasião.'),('Eventos e ações especiais','Campanhas, celebrações e encontros com outros grupos ampliam a experiência. As condições de participação variam conforme o evento.')]))+'<section class="wrap section no-top"><div class="note"><h3>Próximas datas</h3><p>Ainda não há uma programação futura confirmada publicada nesta página. Para visitar o grupo, combine o dia com a equipe; registros de atividades anteriores não funcionam como convite para novos encontros.</p><a class="button green-button" href="contato.html">Combinar uma visita ↗</a></div><h2>Encontros registrados no diário.</h2><div class="cards">'+''.join(card(d) for d in posts[:3])+'</div></section>')
# Consistent breadcrumbs, discovery links and descriptive metadata.
for file in p.glob('*.html'):
 text=file.read_text()
 if file.name!='index.html':
  text=text.replace('<main id="conteudo">','<main id="conteudo"><div class="wrap breadcrumb"><a href="index.html">Início</a><span aria-hidden="true"> / </span><span>'+html.escape(text.split('<title>')[1].split(' | ')[0])+'</span></div>')
 text=text.replace('</head>','<meta property="og:type" content="website"><meta property="og:title" content="'+html.escape(text.split('<title>')[1].split('</title>')[0],quote=True)+'"><meta property="og:image" content="https://lucasmoterani.github.io/rondon194/assets/equipe.jpg"><link rel="canonical" href="https://lucasmoterani.github.io/rondon194/'+('' if file.name=='index.html' else file.name)+'"></head>')
 file.write_text(text)
add_before_footer('contato.html',section('UMA CONVERSA MAIS FÁCIL','Conte para a gente<br>como podemos ajudar.',blocks([('Quero conhecer o grupo','Informe a idade do interessado e pergunte sobre o ramo e a primeira visita. Se você é responsável por uma criança ou adolescente, identifique essa relação na mensagem.'),('Quero colaborar','Apresente sua proposta de doação, serviço ou voluntariado. Conte sua disponibilidade para que a equipe possa avaliar a melhor forma de participação.'),('Já faço parte','Para orientações sobre uma atividade específica, procure a equipe responsável pelo ramo. Confira local, horário e materiais nos comunicados enviados às famílias.')])) )
add_before_footer('galeria.html',section('POR TRÁS DE UM REGISTRO','A memória também<br>se constrói nos detalhes.','''<div class="manifesto"><p class="lead">Um encontro ao ar livre reúne muito mais que pessoas em uma fotografia. Há preparação, troca de experiências e um sentimento de fazer parte de uma história maior.</p><p>O registro desta página foi publicado pelo grupo em agosto de 2026. As histórias do nosso diário ajudam a conhecer outros momentos dessa caminhada, com contexto e informações sobre as atividades e as pessoas que fazem o Rondon acontecer.</p></div><a class="button green-button" href="novidades.html">Explore as histórias do grupo ↗</a>'''))
